import type { SupportedLocale } from './locales';

// Hand-authored translations for long homepage content in the newer locales.
export const longFormTranslations: Record<string, Partial<Record<SupportedLocale, string>>> = {
	'Can I use my phone as a ruler?': { de: 'Kann ich mein Smartphone als Lineal verwenden?', pt: 'Posso usar meu celular como régua?', ar: 'هل يمكنني استخدام هاتفي كمِسطرة؟', bn: 'আমি কি ফোনকে রুলার হিসেবে ব্যবহার করতে পারি?', ur: 'کیا میں اپنے فون کو پیمانے کے طور پر استعمال کر سکتا ہوں؟' },
	'Yes. Open the online ruler on your phone, choose a phone preset in the calibration card, and apply it. Swipe horizontally across the scale to see measurements beyond the screen width.': { de: 'Ja. Öffnen Sie das Online-Lineal auf Ihrem Smartphone, wählen Sie in der Kalibrierung ein Gerätemodell und übernehmen Sie es. Wischen Sie horizontal, um den Maßstab über die Bildschirmbreite hinaus zu sehen.', pt: 'Sim. Abra a régua online no celular, escolha um modelo de telefone na calibração e aplique. Deslize horizontalmente para ver a escala além da largura da tela.', ar: 'نعم. افتح المسطرة على هاتفك، واختر إعدادًا مسبقًا للهاتف في المعايرة ثم طبّقه. مرّر أفقيًا لرؤية أجزاء من التدريج تتجاوز عرض الشاشة.', bn: 'হ্যাঁ। ফোনে অনলাইন রুলার খুলে ক্যালিব্রেশনে ফোনের প্রিসেট বেছে প্রয়োগ করুন। স্ক্রিনের প্রস্থের বাইরে মাপ দেখতে আড়াআড়িভাবে সোয়াইপ করুন।', ur: 'جی ہاں۔ فون پر آن لائن پیمانہ کھولیں، کیلیبریشن میں فون کا پری سیٹ منتخب کرکے لاگو کریں۔ اسکرین کی چوڑائی سے آگے پیمانہ دیکھنے کے لیے افقی طور پر سوائپ کریں۔' },
	'Is there a ruler online?': { de: 'Gibt es ein Lineal online?', pt: 'Existe uma régua online?', ar: 'هل توجد مسطرة عبر الإنترنت؟', bn: 'অনলাইনে কি রুলার আছে?', ur: 'کیا آن لائن پیمانہ دستیاب ہے؟' },
	'Yes. This free online ruler runs in a web browser and offers inch, centimeter, and pixel settings, with millimeter divisions on the centimeter scale.': { de: 'Ja. Dieses kostenlose Online-Lineal läuft im Browser und bietet Zoll, Zentimeter und Pixel. Die Zentimeterskala ist in Millimeter unterteilt.', pt: 'Sim. Esta régua online gratuita funciona no navegador e oferece polegadas, centímetros e pixels, com divisões de milímetros na escala de centímetros.', ar: 'نعم. تعمل هذه المسطرة المجانية في المتصفح وتتيح البوصة والسنتيمتر والبكسل، مع تقسيمات المليمتر على مقياس السنتيمتر.', bn: 'হ্যাঁ। এই বিনামূল্যের অনলাইন রুলার ব্রাউজারে চলে এবং ইঞ্চি, সেন্টিমিটার ও পিক্সেল একক দেয়; সেন্টিমিটার স্কেলে মিলিমিটারের দাগও আছে।', ur: 'جی ہاں۔ یہ مفت آن لائن پیمانہ براؤزر میں چلتا ہے اور انچ، سینٹی میٹر اور پکسل کے پیمانے دیتا ہے؛ سینٹی میٹر پر ملی میٹر کی تقسیم بھی موجود ہے۔' },
	'How to identify 1 inch?': { de: 'Wie erkenne ich einen Zoll?', pt: 'Como identificar 1 polegada?', ar: 'كيف أحدد مقدار بوصة واحدة؟', bn: '১ ইঞ্চি কীভাবে চিনব?', ur: 'ایک انچ کی پیمائش کیسے پہچانیں؟' },
	'After calibrating, switch the ruler to inches. The distance from 0 to the mark labeled 1 is one inch, equal to 2.54 centimeters. Check the display against a physical ruler for actual-size accuracy.': { de: 'Wechseln Sie nach der Kalibrierung zu Zoll. Der Abstand von 0 bis zur Markierung 1 beträgt einen Zoll, also 2,54 Zentimeter. Vergleichen Sie den Bildschirm für die Originalgröße mit einem echten Lineal.', pt: 'Após calibrar, mude a régua para polegadas. A distância de 0 até a marca 1 é uma polegada, equivalente a 2,54 centímetros. Compare a tela com uma régua física para confirmar o tamanho real.', ar: 'بعد المعايرة، اختر البوصة. المسافة من الصفر إلى العلامة 1 تساوي بوصة واحدة، أي 2.54 سنتيمتر. قارن الشاشة بمسطرة فعلية للتحقق من الحجم الحقيقي.', bn: 'ক্যালিব্রেশনের পর রুলারকে ইঞ্চিতে বদলান। ০ থেকে ১ চিহ্ন পর্যন্ত দূরত্ব এক ইঞ্চি, যা ২.৫৪ সেন্টিমিটারের সমান। প্রকৃত আকার যাচাই করতে আসল রুলারের সঙ্গে মিলিয়ে নিন।', ur: 'کیلیبریشن کے بعد پیمانے کو انچ پر تبدیل کریں۔ صفر سے 1 کے نشان تک فاصلہ ایک انچ، یعنی 2.54 سینٹی میٹر ہے۔ اصل سائز کی تصدیق کے لیے اسے حقیقی پیمانے سے ملائیں۔' },
	'How to measure cm online?': { de: 'Wie messe ich online in Zentimetern?', pt: 'Como medir em centímetros online?', ar: 'كيف أقيس بالسنتيمتر عبر الإنترنت؟', bn: 'অনলাইনে সেন্টিমিটারে কীভাবে মাপব?', ur: 'آن لائن سینٹی میٹر میں پیمائش کیسے کریں؟' },
	"Calibrate your screen, select cm, and line up the object's starting edge with 0. Read the numbered centimeter marks, then count the small divisions; each small division is 1 mm, or 0.1 cm.": { de: 'Kalibrieren Sie den Bildschirm, wählen Sie cm und richten Sie die Anfangskante des Gegenstands an 0 aus. Lesen Sie die Zentimetermarken ab und zählen Sie die kleinen Striche: Jeder entspricht 1 mm oder 0,1 cm.', pt: 'Calibre a tela, selecione cm e alinhe a borda inicial do objeto com o zero. Leia as marcas dos centímetros e conte as divisões menores; cada uma vale 1 mm, ou 0,1 cm.', ar: 'عاير الشاشة واختر cm وضع بداية الجسم عند الصفر. اقرأ علامات السنتيمتر ثم عدّ التقسيمات الصغيرة؛ كل تقسيم يساوي 1 مم أو 0.1 سم.', bn: 'স্ক্রিন ক্যালিব্রেট করে cm বেছে নিন এবং বস্তুর শুরুর প্রান্ত ০-তে রাখুন। সেন্টিমিটারের সংখ্যা পড়ে ছোট দাগগুলো গুনুন; প্রতিটি ১ মিমি বা ০.১ সেমি।', ur: 'اسکرین کیلیبریٹ کریں، cm منتخب کریں اور چیز کا ابتدائی کنارہ صفر پر رکھیں۔ سینٹی میٹر کے نمبروں کے بعد چھوٹی تقسیمیں گنیں؛ ہر تقسیم 1 ملی میٹر یا 0.1 سینٹی میٹر ہے۔' },
	'Can a smartphone measure?': { de: 'Kann ein Smartphone messen?', pt: 'Um smartphone consegue medir?', ar: 'هل يستطيع الهاتف الذكي القياس؟', bn: 'স্মার্টফোন কি মাপতে পারে?', ur: 'کیا اسمارٹ فون پیمائش کر سکتا ہے؟' },
	'A smartphone can show an on-screen ruler for measuring small objects beside its display. Calibrate the phone first; browser and screen differences mean the result is an estimate until checked against a known reference.': { de: 'Ein Smartphone kann ein Bildschirm-Lineal anzeigen, mit dem kleine Gegenstände neben dem Display gemessen werden. Kalibrieren Sie es zuerst. Wegen unterschiedlicher Browser und Bildschirme ist das Ergebnis zunächst eine Schätzung, bis Sie es mit einer bekannten Referenz prüfen.', pt: 'Um smartphone pode exibir uma régua na tela para medir objetos pequenos ao lado do visor. Calibre o telefone primeiro; diferenças de navegador e tela fazem do resultado uma estimativa até ser comparado a uma referência conhecida.', ar: 'يمكن للهاتف عرض مسطرة على الشاشة لقياس الأشياء الصغيرة بجانبها. عاير الهاتف أولًا؛ فاختلاف المتصفح والشاشة يجعل النتيجة تقديرية حتى تقارنها بمرجع معروف.', bn: 'স্মার্টফোনে স্ক্রিন রুলার দেখিয়ে ডিসপ্লের পাশে ছোট বস্তু মাপা যায়। আগে ফোন ক্যালিব্রেট করুন; পরিচিত মাপের সঙ্গে যাচাই না করা পর্যন্ত ব্রাউজার ও স্ক্রিনের পার্থক্যের কারণে ফলটি আনুমানিক।', ur: 'اسمارٹ فون پر اسکرین کا پیمانہ دکھا کر اس کے پاس چھوٹی چیزیں ناپی جا سکتی ہیں۔ پہلے فون کیلیبریٹ کریں؛ براؤزر اور اسکرین کے فرق کی وجہ سے معلوم حوالے سے جانچنے تک نتیجہ اندازاً ہوگا۔' },
	'Can a smart phone measure?': { de: 'Kann ein Smartphone messen?', pt: 'Um smartphone consegue medir?', ar: 'هل يستطيع الهاتف الذكي القياس؟', bn: 'স্মার্টফোন কি মাপতে পারে?', ur: 'کیا اسمارٹ فون پیمائش کر سکتا ہے؟' },
	'Yes. A smart phone can measure short objects with an on-screen ruler. Calibrate the display first, align one end with zero, and verify close measurements against a physical ruler.': { de: 'Ja. Mit einem Bildschirm-Lineal lassen sich kurze Gegenstände messen. Kalibrieren Sie zuerst das Display, richten Sie ein Ende an der Null aus und prüfen Sie genaue Messungen mit einem echten Lineal.', pt: 'Sim. Um smartphone pode medir objetos pequenos com uma régua na tela. Calibre o visor, alinhe uma extremidade ao zero e confira medidas precisas com uma régua física.', ar: 'نعم. يمكن للهاتف قياس الأشياء القصيرة بمسطرة على الشاشة. عاير الشاشة أولًا، وضع أحد الأطراف عند الصفر، وتحقق من القياسات الدقيقة بمسطرة فعلية.', bn: 'হ্যাঁ। স্ক্রিন রুলার দিয়ে স্মার্টফোনে ছোট বস্তু মাপা যায়। আগে ডিসপ্লে ক্যালিব্রেট করুন, এক প্রান্ত শূন্যে মিলিয়ে নিন এবং সূক্ষ্ম মাপ আসল রুলারে যাচাই করুন।', ur: 'جی ہاں۔ اسکرین کے پیمانے سے اسمارٹ فون پر چھوٹی چیزیں ناپی جا سکتی ہیں۔ پہلے ڈسپلے کیلیبریٹ کریں، ایک سرا صفر پر رکھیں اور درست پیمائش حقیقی پیمانے سے جانچیں۔' },
	'Can I use my camera as a ruler?': { de: 'Kann ich meine Kamera als Lineal verwenden?', pt: 'Posso usar a câmera como régua?', ar: 'هل يمكنني استخدام الكاميرا كمِسطرة؟', bn: 'আমি কি ক্যামেরাকে রুলার হিসেবে ব্যবহার করতে পারি?', ur: 'کیا میں کیمرے کو پیمانے کے طور پر استعمال کر سکتا ہوں؟' },
	'This tool does not use the camera. It displays a ruler on the screen instead, so you can align an object beside the scale without granting camera access.': { de: 'Dieses Werkzeug verwendet keine Kamera. Es zeigt ein Lineal auf dem Bildschirm an. Legen Sie einen Gegenstand neben die Skala; ein Kamerazugriff ist nicht nötig.', pt: 'Esta ferramenta não usa a câmera. Ela exibe uma régua na tela para você alinhar um objeto ao lado da escala, sem conceder acesso à câmera.', ar: 'لا تستخدم هذه الأداة الكاميرا؛ بل تعرض مسطرة على الشاشة لتضع الجسم بجانب التدريج دون منح إذن الوصول إلى الكاميرا.', bn: 'এই টুল ক্যামেরা ব্যবহার করে না। বরং স্ক্রিনে রুলার দেখায়, তাই ক্যামেরার অনুমতি ছাড়াই স্কেলের পাশে বস্তু মিলিয়ে নিতে পারেন।', ur: 'یہ ٹول کیمرہ استعمال نہیں کرتا۔ یہ اسکرین پر پیمانہ دکھاتا ہے تاکہ کیمرے کی اجازت دیے بغیر چیز کو اس کے ساتھ رکھ سکیں۔' },
	'Can we measure online?': { de: 'Kann man online messen?', pt: 'É possível medir online?', ar: 'هل يمكن القياس عبر الإنترنت؟', bn: 'অনলাইনে কি মাপা যায়?', ur: 'کیا آن لائن پیمائش ممکن ہے؟' },
	'Yes. Use a browser ruler for quick length checks: calibrate the display, align the object with zero, and read its endpoint. Confirm precision measurements with a physical ruler or caliper.': { de: 'Ja. Verwenden Sie das Browser-Lineal für schnelle Längenprüfungen: Kalibrieren Sie das Display, richten Sie den Gegenstand an der Null aus und lesen Sie das Ende ab. Präzise Messungen sollten Sie mit einem echten Lineal oder Messschieber prüfen.', pt: 'Sim. Use uma régua no navegador para verificações rápidas: calibre a tela, alinhe o objeto ao zero e leia a outra extremidade. Confirme medidas precisas com régua física ou paquímetro.', ar: 'نعم. استخدم مسطرة المتصفح لفحص الأطوال بسرعة: عاير الشاشة، وضع الجسم عند الصفر واقرأ الطرف الآخر. تحقق من القياسات الدقيقة بمسطرة فعلية أو قدمة قياس.', bn: 'হ্যাঁ। দ্রুত দৈর্ঘ্য যাচাই করতে ব্রাউজার রুলার ব্যবহার করুন: ডিসপ্লে ক্যালিব্রেট করে বস্তুটি শূন্যে মিলিয়ে শেষ প্রান্ত পড়ুন। নির্ভুল মাপ আসল রুলার বা ক্যালিপারে যাচাই করুন।', ur: 'جی ہاں۔ لمبائی جلدی جانچنے کے لیے براؤزر پیمانہ استعمال کریں: ڈسپلے کیلیبریٹ کریں، چیز کا سرا صفر پر رکھیں اور دوسرا سرا پڑھیں۔ درست پیمائش حقیقی پیمانے یا کیلپر سے تصدیق کریں۔' },
	'How to read a ruler online?': { de: 'Wie liest man ein Online-Lineal ab?', pt: 'Como ler uma régua online?', ar: 'كيف أقرأ المسطرة عبر الإنترنت؟', bn: 'অনলাইন রুলার কীভাবে পড়ব?', ur: 'آن لائن پیمانہ کیسے پڑھیں؟' },
	"Start at zero and read the mark where the object's other edge ends. Larger numbered marks show centimeters or inches; on the centimeter scale, each of ten small divisions equals one millimeter.": { de: 'Beginnen Sie bei null und lesen Sie die Markierung am anderen Ende des Gegenstands ab. Große Zahlen zeigen Zentimeter oder Zoll; auf der Zentimeterskala entspricht jeder der zehn kleinen Striche einem Millimeter.', pt: 'Comece no zero e leia a marca onde termina a outra extremidade do objeto. As marcas numeradas maiores indicam centímetros ou polegadas; na escala em centímetros, cada uma das dez divisões pequenas vale um milímetro.', ar: 'ابدأ من الصفر واقرأ العلامة عند الطرف الآخر للجسم. تشير الأرقام الكبيرة إلى السنتيمتر أو البوصة؛ وعلى مقياس السنتيمتر، يساوي كل واحد من الأقسام الصغيرة العشرة مليمترًا واحدًا.', bn: 'শূন্য থেকে শুরু করে বস্তুর অন্য প্রান্তের দাগ পড়ুন। বড় সংখ্যার দাগ সেন্টিমিটার বা ইঞ্চি দেখায়; সেন্টিমিটার স্কেলে দশটি ছোট দাগের প্রতিটি এক মিলিমিটার।', ur: 'صفر سے آغاز کریں اور چیز کے دوسرے سرے پر نشان پڑھیں۔ بڑے نمبر سینٹی میٹر یا انچ بتاتے ہیں؛ سینٹی میٹر پیمانے کی دس چھوٹی تقسیموں میں سے ہر ایک ایک ملی میٹر ہے۔' },
	'How to view ruler in Word Online?': { de: 'Wie zeige ich das Lineal in Word Online an?', pt: 'Como exibir a régua no Word Online?', ar: 'كيف أعرض المسطرة في Word Online؟', bn: 'Word Online-এ রুলার কীভাবে দেখব?', ur: 'Word Online میں پیمانہ کیسے دیکھیں؟' },
	"Open your document and choose View, then Ruler. This shows Word's page-layout ruler for document formatting. It is separate from an on-screen ruler for measuring physical objects.": { de: 'Öffnen Sie Ihr Dokument und wählen Sie „Ansicht“ und dann „Lineal“. Damit wird das Layout-Lineal von Word zur Dokumentformatierung angezeigt. Es ist nicht dasselbe wie ein Bildschirm-Lineal zum Messen echter Gegenstände.', pt: 'Abra o documento e selecione Exibir e depois Régua. Isso mostra a régua de layout do Word para formatar o documento. Ela é diferente de uma régua na tela usada para medir objetos físicos.', ar: 'افتح المستند واختر عرض ثم مسطرة. يعرض ذلك مسطرة تخطيط الصفحة في Word لتنسيق المستند، وهي تختلف عن مسطرة الشاشة المستخدمة لقياس الأشياء الفعلية.', bn: 'ডকুমেন্ট খুলে View, তারপর Ruler নির্বাচন করুন। এটি ডকুমেন্ট ফরম্যাট করার জন্য Word-এর পেজ-লেআউট রুলার দেখায়। এটি বাস্তব বস্তু মাপার স্ক্রিন রুলার থেকে আলাদা।', ur: 'دستاویز کھولیں، View اور پھر Ruler منتخب کریں۔ اس سے دستاویز کی فارمیٹنگ کے لیے Word کا صفحہ لے آؤٹ پیمانہ دکھائی دے گا۔ یہ حقیقی چیزیں ناپنے والے اسکرین پیمانے سے الگ ہے۔' },
	'How to add a ruler on Word Online?': { de: 'Wie füge ich in Word Online ein Lineal hinzu?', pt: 'Como adicionar uma régua no Word Online?', ar: 'كيف أضيف مسطرة في Word Online؟', bn: 'Word Online-এ রুলার কীভাবে যোগ করব?', ur: 'Word Online میں پیمانہ کیسے شامل کریں؟' },
	'Word for the web displays its ruler from View > Ruler; it is a layout aid rather than an object inserted into the document. For an actual-size screen scale, use this online ruler and calibrate your display.': { de: 'Word im Web zeigt das Lineal über „Ansicht > Lineal“ an. Es ist eine Layout-Hilfe und kein Objekt im Dokument. Für eine Bildschirm-Skala in Originalgröße verwenden Sie dieses Online-Lineal und kalibrieren Sie Ihr Display.', pt: 'O Word para a web mostra a régua em Exibir > Régua; ela ajuda no layout e não é inserida no documento. Para uma escala real na tela, use esta régua online e calibre o visor.', ar: 'يعرض Word للويب المسطرة من عرض > مسطرة؛ وهي أداة لتخطيط الصفحة وليست عنصرًا داخل المستند. للحصول على مقياس فعلي على الشاشة، استخدم هذه المسطرة وعاير الشاشة.', bn: 'ওয়েবের Word-এ View > Ruler থেকে রুলার দেখা যায়; এটি লেআউটের সহায়ক, ডকুমেন্টে যোগ করা বস্তু নয়। স্ক্রিনে প্রকৃত আকারের স্কেলের জন্য এই অনলাইন রুলার ব্যবহার করে ডিসপ্লে ক্যালিব্রেট করুন।', ur: 'Word for the web میں View > Ruler سے پیمانہ دکھایا جاتا ہے؛ یہ صفحے کی ترتیب میں مدد دیتا ہے، دستاویز میں شامل ہونے والی چیز نہیں۔ اسکرین پر اصل سائز کا پیمانہ دیکھنے کے لیے یہ آن لائن پیمانہ استعمال کریں اور ڈسپلے کیلیبریٹ کریں۔' },
	'How to show a ruler in PowerPoint Online?': { de: 'Wie zeige ich in PowerPoint Online ein Lineal an?', pt: 'Como exibir uma régua no PowerPoint Online?', ar: 'كيف أُظهر المسطرة في PowerPoint Online؟', bn: 'PowerPoint Online-এ রুলার কীভাবে দেখাব?', ur: 'PowerPoint Online میں پیمانہ کیسے دکھائیں؟' },
	"PowerPoint for the web does not currently display rulers or gridlines. It uses smart guides to help align slide objects. To use PowerPoint's rulers, open the presentation in the desktop app and select View > Ruler.": { de: 'PowerPoint im Web zeigt derzeit keine Lineale oder Gitternetzlinien an. Intelligente Hilfslinien helfen beim Ausrichten von Folienobjekten. Für Lineale öffnen Sie die Präsentation in der Desktop-App und wählen „Ansicht > Lineal“.', pt: 'O PowerPoint para a web não exibe réguas ou linhas de grade no momento. Ele usa guias inteligentes para alinhar objetos. Para usar as réguas do PowerPoint, abra a apresentação no aplicativo para computador e selecione Exibir > Régua.', ar: 'لا يعرض PowerPoint للويب حاليًا المساطر أو خطوط الشبكة، ويستخدم أدلة ذكية لمحاذاة عناصر الشريحة. لاستخدام مساطر PowerPoint، افتح العرض في تطبيق الكمبيوتر واختر عرض > مسطرة.', bn: 'PowerPoint for the web-এ বর্তমানে রুলার বা গ্রিডলাইন দেখা যায় না। স্লাইডের বস্তু সারিবদ্ধ করতে স্মার্ট গাইড ব্যবহার হয়। PowerPoint রুলার ব্যবহার করতে ডেস্কটপ অ্যাপে প্রেজেন্টেশন খুলে View > Ruler নির্বাচন করুন।', ur: 'PowerPoint for the web فی الحال پیمانے یا گرڈ لائنز نہیں دکھاتا۔ سلائیڈ کے عناصر سیدھ میں رکھنے کے لیے اسمارٹ گائیڈز استعمال ہوتے ہیں۔ PowerPoint کے پیمانے کے لیے پریزنٹیشن ڈیسک ٹاپ ایپ میں کھول کر View > Ruler منتخب کریں۔' },
	'How to use online ruler?': { de: 'Wie verwende ich ein Online-Lineal?', pt: 'Como usar uma régua online?', ar: 'كيف أستخدم مسطرة عبر الإنترنت؟', bn: 'অনলাইন রুলার কীভাবে ব্যবহার করব?', ur: 'آن لائن پیمانہ کیسے استعمال کریں؟' },
	'Choose centimeters or inches, calibrate with a screen preset or standard card, and place the object beside the zero mark. Swipe across the ruler on a phone to reach the full scale; use a physical tool to verify close tolerances.': { de: 'Wählen Sie Zentimeter oder Zoll, kalibrieren Sie mit einem Bildschirm-Preset oder einer Standardkarte und legen Sie den Gegenstand an die Nullmarkierung. Wischen Sie auf dem Smartphone über das Lineal, um die ganze Skala zu sehen. Prüfen Sie enge Toleranzen mit einem echten Messwerkzeug.', pt: 'Escolha centímetros ou polegadas, calibre com uma predefinição de tela ou cartão padrão e coloque o objeto ao lado do zero. No celular, deslize pela régua para ver toda a escala; confirme tolerâncias rigorosas com uma ferramenta física.', ar: 'اختر السنتيمتر أو البوصة، وعاير بإعداد الشاشة أو بطاقة قياسية، ثم ضع الجسم بجانب علامة الصفر. مرّر على المسطرة في الهاتف لرؤية التدريج كاملًا؛ واستخدم أداة فعلية للتحقق من القياسات الدقيقة.', bn: 'সেন্টিমিটার বা ইঞ্চি বেছে স্ক্রিন প্রিসেট বা স্ট্যান্ডার্ড কার্ড দিয়ে ক্যালিব্রেট করুন, তারপর বস্তুটি শূন্য দাগে রাখুন। ফোনে পুরো স্কেল দেখতে রুলারের ওপর সোয়াইপ করুন; সূক্ষ্ম সহনসীমা আসল যন্ত্রে যাচাই করুন।', ur: 'سینٹی میٹر یا انچ منتخب کریں، اسکرین پری سیٹ یا معیاری کارڈ سے کیلیبریٹ کریں اور چیز کو صفر کے نشان پر رکھیں۔ فون پر پورا پیمانہ دیکھنے کے لیے سوائپ کریں؛ باریک درستگی کے لیے حقیقی آلہ استعمال کریں۔' },
	'How to add ruler in Word Online?': { de: 'Wie füge ich in Word Online ein Lineal hinzu?', pt: 'Como adicionar uma régua no Word Online?', ar: 'كيف أضيف مسطرة في Word Online؟', bn: 'Word Online-এ রুলার কীভাবে যোগ করব?', ur: 'Word Online میں پیمانہ کیسے شامل کریں؟' },
	'In Word Online, open the View menu and turn on Ruler. That ruler formats the document page; use this site separately when you need to measure a physical object on your screen.': { de: 'Öffnen Sie in Word Online das Menü „Ansicht“ und aktivieren Sie „Lineal“. Dieses Lineal dient der Dokumentformatierung. Verwenden Sie diese Website, wenn Sie einen echten Gegenstand auf dem Bildschirm messen möchten.', pt: 'No Word Online, abra o menu Exibir e ative Régua. Essa régua formata a página do documento; use este site quando quiser medir um objeto físico na tela.', ar: 'في Word Online، افتح قائمة عرض وشغّل المسطرة. هذه المسطرة لتنسيق صفحة المستند؛ استخدم هذا الموقع لقياس جسم فعلي على الشاشة.', bn: 'Word Online-এ View মেনু খুলে Ruler চালু করুন। ওই রুলার ডকুমেন্টের পৃষ্ঠা ফরম্যাট করে; স্ক্রিনে বাস্তব বস্তু মাপতে এই সাইট ব্যবহার করুন।', ur: 'Word Online میں View مینو کھول کر Ruler فعال کریں۔ وہ پیمانہ دستاویز کے صفحے کی فارمیٹنگ کے لیے ہے؛ اسکرین پر حقیقی چیز ناپنے کے لیے یہ سائٹ استعمال کریں۔' },
	'How to use a ruler online?': { de: 'Wie verwende ich ein Lineal online?', pt: 'Como usar uma régua online?', ar: 'كيف أستخدم المسطرة عبر الإنترنت؟', bn: 'অনলাইনে রুলার কীভাবে ব্যবহার করব?', ur: 'آن لائن پیمانہ کیسے استعمال کریں؟' },
	'Open the ruler workspace, select cm, in, or px, calibrate your display, and align the object with the zero mark. Read the endpoint on the scale and verify precision work with a physical tool.': { de: 'Öffnen Sie den Messbereich, wählen Sie cm, in oder px, kalibrieren Sie den Bildschirm und richten Sie den Gegenstand an der Nullmarkierung aus. Lesen Sie das Ende auf der Skala ab und prüfen Sie genaue Arbeiten mit einem echten Messwerkzeug.', pt: 'Abra a área da régua, selecione cm, in ou px, calibre a tela e alinhe o objeto ao zero. Leia a outra extremidade na escala e confirme trabalhos de precisão com uma ferramenta física.', ar: 'افتح مساحة المسطرة، واختر cm أو in أو px، وعاير الشاشة ثم ضع الجسم عند الصفر. اقرأ الطرف الآخر على التدريج وتحقق من الأعمال الدقيقة بأداة فعلية.', bn: 'রুলার কর্মক্ষেত্র খুলে cm, in বা px বেছে নিন, ডিসপ্লে ক্যালিব্রেট করে বস্তুটি শূন্যে মিলিয়ে নিন। স্কেলে শেষ প্রান্ত পড়ুন এবং নির্ভুল কাজ আসল যন্ত্রে যাচাই করুন।', ur: 'پیمانے کی جگہ کھولیں، cm، in یا px منتخب کریں، ڈسپلے کیلیبریٹ کرکے چیز کو صفر پر رکھیں۔ دوسرے سرے کا نشان پڑھیں اور درست کام حقیقی آلے سے جانچیں۔' },
	'An online ruler makes it easy to check the length of a small object when a physical ruler is not nearby. This free online ruler runs in your browser on a phone, tablet, or computer, with no app to install and no account to create. Open the ruler workspace, choose a unit, calibrate the display, and line up the object with zero. Read the mark beside its other end to get a quick measurement for crafts, schoolwork, packages, and everyday checks.': { de: 'Mit einem Online-Lineal lässt sich die Länge kleiner Gegenstände prüfen, wenn gerade kein echtes Lineal zur Hand ist. Dieses kostenlose Lineal läuft ohne Installation und Konto im Browser auf Smartphone, Tablet oder Computer. Öffnen Sie den Messbereich, wählen Sie eine Einheit, kalibrieren Sie den Bildschirm und richten Sie den Gegenstand an der Null aus. Lesen Sie die Markierung am anderen Ende ab – praktisch für Bastelarbeiten, Schule, Pakete und schnelle Alltagsmessungen.', pt: 'Uma régua online facilita conferir o comprimento de um objeto pequeno quando não há uma régua física por perto. Esta ferramenta gratuita funciona no navegador do celular, tablet ou computador, sem instalar aplicativo ou criar conta. Abra a área de medição, escolha uma unidade, calibre a tela e alinhe o objeto ao zero. Leia a marca na outra extremidade para medir rapidamente materiais de artesanato, itens escolares, encomendas e objetos do dia a dia.', ar: 'تساعدك المسطرة عبر الإنترنت على معرفة طول جسم صغير عندما لا تتوفر مسطرة فعلية. تعمل هذه الأداة المجانية في متصفح الهاتف أو الجهاز اللوحي أو الكمبيوتر، دون تثبيت تطبيق أو إنشاء حساب. افتح مساحة القياس، واختر وحدة، وعاير الشاشة، وضع الجسم عند الصفر. اقرأ العلامة عند الطرف الآخر لقياس سريع للأعمال اليدوية والواجبات والطرود والأغراض اليومية.', bn: 'কাছে আসল রুলার না থাকলে অনলাইন রুলার দিয়ে ছোট বস্তুর দৈর্ঘ্য সহজে দেখা যায়। এই বিনামূল্যের টুল ফোন, ট্যাবলেট বা কম্পিউটারের ব্রাউজারে চলে—অ্যাপ ইনস্টল বা অ্যাকাউন্ট খোলার দরকার নেই। মাপার কর্মক্ষেত্র খুলে একক বেছে নিন, ডিসপ্লে ক্যালিব্রেট করে বস্তুটির এক প্রান্ত শূন্যে রাখুন। অন্য প্রান্তের দাগ পড়ে হাতের কাজ, পড়াশোনা, পার্সেল ও দৈনন্দিন জিনিস দ্রুত মাপুন।', ur: 'جب حقیقی پیمانہ قریب نہ ہو تو آن لائن پیمانے سے چھوٹی چیز کی لمبائی آسانی سے دیکھی جا سکتی ہے۔ یہ مفت ٹول فون، ٹیبلٹ یا کمپیوٹر کے براؤزر میں چلتا ہے؛ ایپ انسٹال یا اکاؤنٹ بنانے کی ضرورت نہیں۔ پیمائش کی جگہ کھولیں، اکائی منتخب کریں، ڈسپلے کیلیبریٹ کریں اور چیز کا ایک سرا صفر پر رکھیں۔ دوسرے سرے کا نشان پڑھ کر دستکاری، پڑھائی، پارسل اور روزمرہ کی چیزوں کی فوری پیمائش کریں۔' },
	'Choose online ruler inches when you are following a project or product dimension written in inches. Switch to online ruler in cm for metric measurements, or use the online ruler mm scale when you need to read smaller divisions. The controls let you move between inches, centimeters, and pixels in the workspace. Whether you searched for an online ruler cm, an online ruler in mm, or a mm online ruler, you can select the unit that matches the measurement you need without converting it first. One inch equals 2.54 centimeters, and each centimeter contains ten millimeters.': { de: 'Wählen Sie Zoll, wenn Projekt- oder Produktmaße in Zoll angegeben sind. Für metrische Messungen wechseln Sie zu Zentimetern; kleinere Teilstriche können Sie in Millimetern ablesen. Über die Steuerelemente wechseln Sie zwischen Zoll, Zentimetern und Pixeln. Wählen Sie einfach die passende Einheit, ohne vorher umzurechnen. Ein Zoll entspricht 2,54 Zentimetern, und ein Zentimeter besteht aus zehn Millimetern.', pt: 'Escolha polegadas quando as medidas do projeto ou produto estiverem nessa unidade. Para medidas métricas, use centímetros; para divisões menores, leia a escala em milímetros. Os controles permitem alternar entre polegadas, centímetros e pixels. Selecione a unidade de que precisa sem converter antes. Uma polegada equivale a 2,54 centímetros, e cada centímetro tem dez milímetros.', ar: 'اختر البوصة عندما تكون أبعاد المشروع أو المنتج مكتوبة بها. استخدم السنتيمتر للقياس المتري، واقرأ التدريجات الأصغر بالمليمتر. تتيح لك عناصر التحكم التبديل بين البوصة والسنتيمتر والبكسل. اختر الوحدة المناسبة مباشرة دون تحويل مسبق. البوصة الواحدة تساوي 2.54 سنتيمتر، وكل سنتيمتر يتكون من عشرة مليمترات.', bn: 'প্রকল্প বা পণ্যের মাপ ইঞ্চিতে দেওয়া থাকলে ইঞ্চি বেছে নিন। মেট্রিক মাপের জন্য সেন্টিমিটার এবং ছোট দাগ পড়তে মিলিমিটার ব্যবহার করুন। নিয়ন্ত্রণ থেকে ইঞ্চি, সেন্টিমিটার ও পিক্সেলের মধ্যে বদলানো যায়। আগে রূপান্তর না করেই প্রয়োজনীয় একক বেছে নিন। এক ইঞ্চি ২.৫৪ সেন্টিমিটার এবং এক সেন্টিমিটারে দশ মিলিমিটার।', ur: 'اگر کسی منصوبے یا مصنوعات کا سائز انچ میں ہو تو انچ منتخب کریں۔ میٹرک پیمائش کے لیے سینٹی میٹر اور چھوٹی تقسیموں کے لیے ملی میٹر استعمال کریں۔ کنٹرولز سے انچ، سینٹی میٹر اور پکسل کے درمیان تبدیلی کریں۔ پہلے تبدیل کیے بغیر مطلوبہ اکائی منتخب کریں۔ ایک انچ 2.54 سینٹی میٹر اور ایک سینٹی میٹر دس ملی میٹر کے برابر ہے۔' },
	'A screen ruler can only represent real-world length accurately when its scale is calibrated for the display you are using. Screen sizes, pixel density, browser zoom, and device settings vary, so an automatic estimate may not match a physical ruler. Use a device preset as a starting point, enter your display details, or align the on-screen guide with a standard card or known ruler. After calibration, an online ruler actual size view can serve for everyday estimates. For an online ruler inches actual size or an online ruler to scale, keep browser zoom unchanged and check the calibration again whenever you switch devices or adjust display settings.': { de: 'Ein Bildschirm-Lineal zeigt reale Längen nur dann genauer an, wenn es für Ihr Display kalibriert ist. Bildschirmgröße, Pixeldichte, Browserzoom und Geräteeinstellungen unterscheiden sich; eine automatische Schätzung kann daher von einem echten Lineal abweichen. Beginnen Sie mit einem Geräteprofil, geben Sie Displaydaten ein oder gleichen Sie die Bildschirmhilfe mit einer Standardkarte oder einem bekannten Lineal ab. Danach eignet sich die Anzeige für Alltagsschätzungen. Lassen Sie den Browserzoom unverändert und kalibrieren Sie nach einem Geräte- oder Einstellungswechsel erneut.', pt: 'Uma régua na tela só representa comprimentos reais com precisão quando é calibrada para o visor usado. Tamanho, densidade de pixels, zoom do navegador e configurações variam; por isso, a estimativa automática pode diferir de uma régua física. Comece com um modelo de dispositivo, informe os dados da tela ou alinhe a guia a um cartão padrão ou régua conhecida. Depois de calibrada, ela serve para estimativas do dia a dia. Mantenha o zoom e calibre novamente se trocar de dispositivo ou alterar as configurações.', ar: 'لا تقيس مسطرة الشاشة الطول الحقيقي بدقة إلا بعد معايرتها للشاشة المستخدمة. تختلف أحجام الشاشات وكثافة البكسل وتكبير المتصفح وإعدادات الأجهزة، لذلك قد لا يطابق التقدير التلقائي مسطرة فعلية. ابدأ بإعداد جهاز جاهز، أو أدخل بيانات الشاشة، أو طابق الدليل المعروض مع بطاقة قياسية أو مسطرة معروفة. بعد المعايرة تصلح للتقديرات اليومية. أبقِ تكبير المتصفح ثابتًا وأعد المعايرة عند تغيير الجهاز أو إعدادات العرض.', bn: 'স্ক্রিন রুলার বাস্তব দৈর্ঘ্য ঠিকভাবে দেখাতে হলে ব্যবহৃত ডিসপ্লের জন্য ক্যালিব্রেট করতে হয়। স্ক্রিনের আকার, পিক্সেল ঘনত্ব, ব্রাউজার জুম ও ডিভাইস সেটিং ভিন্ন হয়, তাই স্বয়ংক্রিয় অনুমান আসল রুলারের সঙ্গে নাও মিলতে পারে। শুরুতে ডিভাইস প্রিসেট নিন, ডিসপ্লের তথ্য দিন অথবা স্ক্রিনের গাইডকে স্ট্যান্ডার্ড কার্ড বা পরিচিত রুলারের সঙ্গে মিলিয়ে নিন। ক্যালিব্রেশনের পর দৈনন্দিন আনুমানিক মাপে ব্যবহার করুন। ব্রাউজার জুম অপরিবর্তিত রাখুন এবং ডিভাইস বা ডিসপ্লে সেটিং বদলালে আবার ক্যালিব্রেট করুন।', ur: 'اسکرین کا پیمانہ حقیقی لمبائی صرف اسی وقت درست دکھا سکتا ہے جب اسے آپ کے ڈسپلے کے مطابق کیلیبریٹ کیا گیا ہو۔ اسکرین کا سائز، پکسل کثافت، براؤزر زوم اور ڈیوائس کی ترتیبات مختلف ہوتی ہیں، اس لیے خودکار اندازہ حقیقی پیمانے سے مختلف ہو سکتا ہے۔ آغاز کے لیے ڈیوائس پری سیٹ استعمال کریں، ڈسپلے کی تفصیل درج کریں یا اسکرین گائیڈ کو معیاری کارڈ یا معلوم پیمانے سے ملائیں۔ کیلیبریشن کے بعد اسے روزمرہ کے اندازوں کے لیے استعمال کریں۔ براؤزر زوم نہ بدلیں اور ڈیوائس یا ڈسپلے کی ترتیبات بدلنے پر دوبارہ کیلیبریٹ کریں۔' },
	'Looking for a 12 inch online ruler or online ruler 12 inch scale? The workspace lets you view and adjust a long scale, then scroll along it on a smaller screen to reach the section you need. A phone screen may show only part of the ruler at once, while a larger monitor can display more of it. Select inches, calibrate the display, and compare the scale with a known length before relying on it. The same online ruler tool can also show centimeters and pixels, so it works for different tasks and reference systems.': { de: 'Suchen Sie ein 12-Zoll-Lineal? Im Messbereich können Sie eine lange Skala anzeigen und anpassen. Auf kleinen Bildschirmen scrollen Sie zum benötigten Abschnitt; ein größerer Monitor zeigt mehr davon gleichzeitig. Wählen Sie Zoll, kalibrieren Sie das Display und vergleichen Sie die Skala mit einer bekannten Länge. Das Lineal zeigt auch Zentimeter und Pixel für unterschiedliche Aufgaben.', pt: 'Precisa de uma régua de 12 polegadas? Na área de trabalho, você pode visualizar e ajustar uma escala longa e, em telas menores, deslizar até o trecho necessário. Um celular pode mostrar apenas parte da régua, enquanto um monitor maior exibe mais. Selecione polegadas, calibre a tela e compare a escala com um comprimento conhecido. A ferramenta também mostra centímetros e pixels.', ar: 'هل تبحث عن مسطرة بطول 12 بوصة؟ تتيح مساحة العمل عرض تدريج طويل وضبطه، ثم التمرير على الشاشة الصغيرة للوصول إلى الجزء المطلوب. قد تعرض شاشة الهاتف جزءًا فقط، بينما تُظهر الشاشة الأكبر جزءًا أطول. اختر البوصة، وعاير الشاشة، وقارن التدريج بطول معروف قبل الاعتماد عليه. وتعرض الأداة أيضًا السنتيمترات والبكسل.', bn: '১২ ইঞ্চি রুলার খুঁজছেন? কর্মক্ষেত্রে লম্বা স্কেল দেখা ও সমন্বয় করা যায়; ছোট স্ক্রিনে প্রয়োজনীয় অংশে যেতে স্ক্রল করুন। ফোনে একবারে রুলারের কিছু অংশ দেখা যেতে পারে, বড় মনিটরে আরও বেশি দেখা যায়। ইঞ্চি বেছে স্ক্রিন ক্যালিব্রেট করুন এবং ব্যবহার করার আগে পরিচিত দৈর্ঘ্যের সঙ্গে মিলিয়ে নিন। একই টুলে সেন্টিমিটার ও পিক্সেলও দেখা যায়।', ur: 'کیا آپ 12 انچ کا آن لائن پیمانہ چاہتے ہیں؟ کام کی جگہ میں لمبا پیمانہ دیکھ اور ایڈجسٹ کر سکتے ہیں، اور چھوٹی اسکرین پر مطلوبہ حصے تک اسکرول کریں۔ فون پر پیمانے کا صرف کچھ حصہ نظر آ سکتا ہے، جبکہ بڑے مانیٹر پر زیادہ حصہ دکھتا ہے۔ انچ منتخب کریں، ڈسپلے کیلیبریٹ کریں اور استعمال سے پہلے معلوم لمبائی سے ملائیں۔ یہی ٹول سینٹی میٹر اور پکسل بھی دکھاتا ہے۔' },
	'This real online ruler displays a scale on your screen; it does not use your camera to measure objects in a photograph. If you searched for an online ruler camera, no camera access is needed here: place the object beside the visible screen scale instead. The ruler can be positioned along different screen edges, and the workspace offers crosshair coordinates for convenient on-screen checks. A calibrated display can be useful for rough sizing, but browser-based measurement is not a replacement for a precision instrument. For tight tolerances, safety-critical work, or valuable materials, confirm the result with a physical ruler or caliper.': { de: 'Dieses Online-Lineal zeigt eine Skala auf dem Bildschirm und misst keine Gegenstände auf Fotos mit der Kamera. Ein Kamerazugriff ist nicht nötig: Legen Sie den Gegenstand neben die sichtbare Skala. Das Lineal lässt sich an verschiedenen Bildschirmkanten platzieren; Koordinaten helfen bei schnellen Prüfungen. Ein kalibriertes Display eignet sich für grobe Größenangaben, ersetzt aber kein Präzisionswerkzeug. Prüfen Sie enge Toleranzen, sicherheitskritische Arbeiten und wertvolle Materialien mit einem echten Lineal oder Messschieber.', pt: 'Esta régua online exibe uma escala na tela; não usa a câmera para medir objetos em fotos. Não é necessário acesso à câmera: coloque o objeto ao lado da escala. A régua pode ficar em diferentes bordas da tela, e a área de trabalho mostra coordenadas da mira. Uma tela calibrada ajuda em medidas aproximadas, mas não substitui instrumentos de precisão. Para tolerâncias rigorosas, segurança ou materiais valiosos, confirme com uma régua física ou paquímetro.', ar: 'تعرض هذه المسطرة تدريجًا على الشاشة ولا تستخدم الكاميرا لقياس الأشياء في الصور. لا تحتاج إلى إذن الكاميرا؛ ضع الجسم بجانب التدريج الظاهر. يمكن وضع المسطرة عند حواف مختلفة، كما تعرض مساحة العمل إحداثيات علامة التصويب. تفيد الشاشة المعايرة في تقدير الحجم، لكنها لا تغني عن أدوات الدقة. تحقق من القياسات الدقيقة أو الأعمال الحساسة أو المواد الثمينة بمسطرة فعلية أو قدمة قياس.', bn: 'এই অনলাইন রুলার স্ক্রিনে স্কেল দেখায়; ছবির বস্তু মাপতে ক্যামেরা ব্যবহার করে না। ক্যামেরার অনুমতি লাগে না—বস্তুটি স্ক্রিনের স্কেলের পাশে রাখুন। রুলার স্ক্রিনের বিভিন্ন প্রান্তে রাখা যায় এবং কর্মক্ষেত্রে ক্রসহেয়ার স্থানাঙ্ক দেখা যায়। ক্যালিব্রেট করা ডিসপ্লে মোটামুটি মাপে কাজে লাগে, তবে নির্ভুল যন্ত্রের বিকল্প নয়। সূক্ষ্ম সহনসীমা, নিরাপত্তা-গুরুত্বপূর্ণ কাজ বা মূল্যবান উপকরণ আসল রুলার বা ক্যালিপারে যাচাই করুন।', ur: 'یہ آن لائن پیمانہ اسکرین پر نشان دکھاتا ہے؛ تصویر میں چیزیں ناپنے کے لیے کیمرہ استعمال نہیں کرتا۔ کیمرے کی اجازت درکار نہیں، بس چیز کو اسکرین کے پیمانے کے ساتھ رکھیں۔ پیمانہ اسکرین کے مختلف کناروں پر رکھا جا سکتا ہے اور کام کی جگہ پر کراس ہیئر کے نقاط بھی دکھتے ہیں۔ کیلیبریٹڈ ڈسپلے اندازاً پیمائش کے لیے مفید ہے، مگر درست پیمائشی آلے کا متبادل نہیں۔ باریک برداشت، حفاظتی کام یا قیمتی مواد کے لیے نتیجہ حقیقی پیمانے یا کیلپر سے جانچیں۔' },
	'Start by opening the workspace and selecting inches or centimeters. Calibrate the scale against a known reference, place the item beside its zero point, and read the endpoint. Recheck your setup if browser zoom changes, the browser window moves to another monitor, or you begin using another device. You can use the same steps for a quick package check, a craft measurement, or a classroom demonstration. The goal is a convenient, accessible scale that is ready when you need it. With a careful setup, this online ruler provides a useful actual-size reference right in your browser, wherever you have a screen available.': { de: 'Öffnen Sie zuerst den Messbereich und wählen Sie Zoll oder Zentimeter. Kalibrieren Sie die Skala anhand einer bekannten Referenz, legen Sie den Gegenstand an den Nullpunkt und lesen Sie das Ende ab. Prüfen Sie die Einrichtung erneut, wenn sich Browserzoom, Monitor oder Gerät ändern. So können Sie Pakete, Bastelmaterial oder Dinge im Unterricht schnell messen. Mit sorgfältiger Einrichtung bietet das Online-Lineal eine praktische Größenreferenz direkt im Browser.', pt: 'Abra a área de trabalho e selecione polegadas ou centímetros. Calibre a escala com uma referência conhecida, coloque o item junto ao zero e leia a outra extremidade. Confira a configuração se o zoom mudar, a janela for para outro monitor ou você trocar de dispositivo. Use os mesmos passos para conferir encomendas, trabalhos manuais ou demonstrações em sala. Com a configuração correta, a régua oferece uma referência prática em tamanho real no navegador.', ar: 'ابدأ بفتح مساحة العمل واختر البوصة أو السنتيمتر. عاير التدريج بمرجع معروف، وضع العنصر عند الصفر واقرأ الطرف الآخر. أعد فحص الإعداد إذا تغير تكبير المتصفح أو نُقلت النافذة إلى شاشة أخرى أو استخدمت جهازًا مختلفًا. تنفع الخطوات لفحص طرد أو قياس مشروع يدوي أو عرض تعليمي. مع الإعداد الدقيق، توفر المسطرة مرجعًا عمليًا للحجم الفعلي في المتصفح.', bn: 'কর্মক্ষেত্র খুলে ইঞ্চি বা সেন্টিমিটার বেছে শুরু করুন। পরিচিত মাপের রেফারেন্স দিয়ে স্কেল ক্যালিব্রেট করে জিনিসটির এক প্রান্ত শূন্যে রাখুন এবং অন্য প্রান্ত পড়ুন। ব্রাউজার জুম বদলালে, উইন্ডো অন্য মনিটরে নিলে বা ডিভাইস বদলালে সেটআপ আবার যাচাই করুন। পার্সেল, হাতের কাজ বা শ্রেণিকক্ষের প্রদর্শনে একই ধাপ ব্যবহার করা যায়। ঠিকভাবে সেট করলে ব্রাউজারেই প্রকৃত আকারের কার্যকর রেফারেন্স পাবেন।', ur: 'کام کی جگہ کھول کر انچ یا سینٹی میٹر منتخب کریں۔ معلوم حوالے سے پیمانہ کیلیبریٹ کریں، چیز کو صفر کے پاس رکھیں اور دوسرا سرا پڑھیں۔ براؤزر زوم بدلنے، ونڈو دوسرے مانیٹر پر لے جانے یا ڈیوائس بدلنے پر ترتیب دوبارہ جانچیں۔ یہی طریقہ پارسل، دستکاری یا کلاس کے مظاہرے کے لیے اپنائیں۔ درست ترتیب کے ساتھ یہ آن لائن پیمانہ براؤزر میں حقیقی سائز کا مفید حوالہ فراہم کرتا ہے۔' },
	'A Online Ruler is designed to work without an account. We do not ask you to submit your name, email address, or payment details to use the ruler. Calibration settings may be stored locally in your browser so the ruler can remember your setup on that device.': { de: 'A Online Ruler funktioniert ohne Benutzerkonto. Für die Nutzung des Lineals müssen Sie weder Ihren Namen noch Ihre E-Mail-Adresse oder Zahlungsdaten angeben. Kalibrierungseinstellungen können lokal im Browser gespeichert werden, damit das Lineal Ihre Einrichtung auf diesem Gerät beibehält.', pt: 'O A Online Ruler foi criado para funcionar sem conta. Não solicitamos nome, e-mail ou dados de pagamento para usar a régua. As configurações de calibração podem ser armazenadas localmente no navegador para que a ferramenta se lembre delas neste dispositivo.', ar: 'صُمم A Online Ruler للعمل دون حساب. لا نطلب منك تقديم اسمك أو بريدك الإلكتروني أو بيانات الدفع لاستخدام المسطرة. قد تُحفظ إعدادات المعايرة محليًا في المتصفح كي يتذكر الموقع إعدادك على هذا الجهاز.', bn: 'A Online Ruler অ্যাকাউন্ট ছাড়াই ব্যবহারের জন্য তৈরি। রুলার ব্যবহার করতে আমরা আপনার নাম, ইমেইল ঠিকানা বা পেমেন্ট তথ্য চাই না। এই ডিভাইসে সেটআপ মনে রাখতে ক্যালিব্রেশন সেটিংস ব্রাউজারে স্থানীয়ভাবে সংরক্ষিত হতে পারে।', ur: 'A Online Ruler بغیر اکاؤنٹ کے کام کرنے کے لیے بنایا گیا ہے۔ پیمانہ استعمال کرنے کے لیے ہم آپ کا نام، ای میل یا ادائیگی کی تفصیل نہیں مانگتے۔ اس ڈیوائس پر سیٹ اپ یاد رکھنے کے لیے کیلیبریشن کی ترتیبات براؤزر میں مقامی طور پر محفوظ ہو سکتی ہیں۔' },
	'Our hosting provider may process standard technical information such as an IP address, browser type, device type, and request time to deliver and protect the website.': { de: 'Unser Hosting-Anbieter kann übliche technische Angaben wie IP-Adresse, Browser- und Gerätetyp sowie Zeitpunkt der Anfrage verarbeiten, um die Website bereitzustellen und zu schützen.', pt: 'Nosso provedor de hospedagem pode processar informações técnicas comuns, como endereço IP, tipo de navegador e dispositivo e horário da solicitação, para entregar e proteger o site.', ar: 'قد يعالج مزود الاستضافة معلومات تقنية اعتيادية مثل عنوان IP ونوع المتصفح والجهاز ووقت الطلب لتشغيل الموقع وحمايته.', bn: 'ওয়েবসাইট সরবরাহ ও সুরক্ষার জন্য আমাদের হোস্টিং প্রদানকারী IP ঠিকানা, ব্রাউজার ও ডিভাইসের ধরন এবং অনুরোধের সময়ের মতো সাধারণ প্রযুক্তিগত তথ্য প্রক্রিয়া করতে পারে।', ur: 'ویب سائٹ فراہم کرنے اور محفوظ رکھنے کے لیے ہمارا ہوسٹنگ فراہم کنندہ عام تکنیکی معلومات، مثلاً IP ایڈریس، براؤزر اور ڈیوائس کی قسم اور درخواست کا وقت، پراسیس کر سکتا ہے۔' },
	'Technical information is used to operate, secure, and understand the performance of the website. We do not sell personal information or use ruler measurements to build a profile about you.': { de: 'Technische Informationen dienen dem Betrieb, der Sicherheit und der Leistungsanalyse der Website. Wir verkaufen keine personenbezogenen Daten und erstellen anhand Ihrer Linealmessungen kein Profil.', pt: 'As informações técnicas são usadas para operar e proteger o site e entender seu desempenho. Não vendemos dados pessoais nem usamos as medições da régua para criar um perfil sobre você.', ar: 'تُستخدم المعلومات التقنية لتشغيل الموقع وتأمينه وفهم أدائه. لا نبيع المعلومات الشخصية ولا نستخدم قياسات المسطرة لإنشاء ملف تعريفي عنك.', bn: 'ওয়েবসাইট পরিচালনা, সুরক্ষা ও কার্যকারিতা বোঝার জন্য প্রযুক্তিগত তথ্য ব্যবহার করা হয়। আমরা ব্যক্তিগত তথ্য বিক্রি করি না বা রুলারের মাপ দিয়ে আপনার প্রোফাইল তৈরি করি না।', ur: 'تکنیکی معلومات ویب سائٹ چلانے، محفوظ رکھنے اور کارکردگی سمجھنے کے لیے استعمال ہوتی ہیں۔ ہم ذاتی معلومات فروخت نہیں کرتے اور پیمائشوں سے آپ کا پروفائل نہیں بناتے۔' },
	'The ruler may use browser local storage for calibration preferences. You can clear this data through your browser settings. The site may also use essential technologies required for hosting and security.': { de: 'Das Lineal kann Kalibrierungseinstellungen im lokalen Browserspeicher ablegen. Sie können diese Daten in den Browsereinstellungen löschen. Die Website kann außerdem notwendige Technologien für Hosting und Sicherheit verwenden.', pt: 'A régua pode usar o armazenamento local do navegador para guardar preferências de calibração. Você pode apagar esses dados nas configurações do navegador. O site também pode usar tecnologias essenciais para hospedagem e segurança.', ar: 'قد تستخدم المسطرة التخزين المحلي في المتصفح لحفظ تفضيلات المعايرة. يمكنك حذف هذه البيانات من إعدادات المتصفح. وقد يستخدم الموقع تقنيات أساسية للاستضافة والأمان.', bn: 'ক্যালিব্রেশন পছন্দ সংরক্ষণে রুলার ব্রাউজারের লোকাল স্টোরেজ ব্যবহার করতে পারে। ব্রাউজার সেটিংস থেকে এই তথ্য মুছতে পারবেন। হোস্টিং ও নিরাপত্তার জন্য সাইটটি প্রয়োজনীয় প্রযুক্তিও ব্যবহার করতে পারে।', ur: 'کیلیبریشن کی ترجیحات محفوظ کرنے کے لیے پیمانہ براؤزر کی مقامی اسٹوریج استعمال کر سکتا ہے۔ آپ براؤزر کی ترتیبات سے یہ ڈیٹا حذف کر سکتے ہیں۔ ہوسٹنگ اور سیکیورٹی کے لیے سائٹ ضروری ٹیکنالوجی بھی استعمال کر سکتی ہے۔' },
	'This website may link to services or resources operated by other organizations. Their privacy practices are governed by their own policies, so review those policies before sharing information.': { de: 'Diese Website kann auf Dienste oder Ressourcen anderer Organisationen verweisen. Für deren Datenschutz gelten die jeweiligen Richtlinien. Lesen Sie diese, bevor Sie Informationen weitergeben.', pt: 'Este site pode conter links para serviços ou recursos de outras organizações. As práticas de privacidade são regidas pelas políticas dessas organizações; leia-as antes de compartilhar informações.', ar: 'قد يحتوي هذا الموقع على روابط لخدمات أو موارد تديرها جهات أخرى. تخضع ممارسات الخصوصية لديها لسياساتها الخاصة؛ راجعها قبل مشاركة أي معلومات.', bn: 'এই ওয়েবসাইটে অন্য প্রতিষ্ঠানের পরিষেবা বা রিসোর্সের লিংক থাকতে পারে। তাদের নিজস্ব নীতি অনুযায়ী গোপনীয়তা পরিচালিত হয়; তথ্য দেওয়ার আগে নীতিগুলো পড়ুন।', ur: 'اس ویب سائٹ پر دوسری تنظیموں کی خدمات یا وسائل کے روابط ہو سکتے ہیں۔ ان کی رازداری کی اپنی پالیسیاں ہیں؛ معلومات دینے سے پہلے وہ پالیسیاں دیکھیں۔' },
	'We may update this policy when the website or applicable requirements change. The latest version will always be published on this page.': { de: 'Wir können diese Richtlinie ändern, wenn sich die Website oder geltende Anforderungen ändern. Die aktuelle Fassung wird stets auf dieser Seite veröffentlicht.', pt: 'Podemos atualizar esta política quando o site ou os requisitos aplicáveis mudarem. A versão mais recente estará sempre publicada nesta página.', ar: 'قد نحدّث هذه السياسة عند تغير الموقع أو المتطلبات المعمول بها. ستُنشر أحدث نسخة دائمًا في هذه الصفحة.', bn: 'ওয়েবসাইট বা প্রযোজ্য নিয়ম বদলালে আমরা এই নীতি হালনাগাদ করতে পারি। সর্বশেষ সংস্করণ সবসময় এই পৃষ্ঠায় প্রকাশ করা হবে।', ur: 'ویب سائٹ یا متعلقہ تقاضے بدلنے پر ہم اس پالیسی کو اپ ڈیٹ کر سکتے ہیں۔ تازہ ترین نسخہ ہمیشہ اسی صفحے پر دستیاب ہوگا۔' },
	'You may use A Online Ruler for lawful personal, educational, and business purposes. Please use the website responsibly and do not interfere with its operation, attempt unauthorized access, or misuse automated requests.': { de: 'Sie dürfen A Online Ruler für rechtmäßige private, schulische und geschäftliche Zwecke nutzen. Verwenden Sie die Website verantwortungsvoll, stören Sie den Betrieb nicht, versuchen Sie keinen unbefugten Zugriff und missbrauchen Sie keine automatisierten Anfragen.', pt: 'Você pode usar o A Online Ruler para fins pessoais, educacionais e comerciais legais. Use o site com responsabilidade; não interfira em seu funcionamento, tente acessá-lo sem autorização nem abuse de solicitações automatizadas.', ar: 'يجوز لك استخدام A Online Ruler لأغراض شخصية وتعليمية وتجارية مشروعة. استخدم الموقع بمسؤولية، ولا تعطل تشغيله أو تحاول الوصول غير المصرح به أو تسيء استخدام الطلبات الآلية.', bn: 'আইনসম্মত ব্যক্তিগত, শিক্ষামূলক ও ব্যবসায়িক কাজে A Online Ruler ব্যবহার করতে পারেন। দায়িত্বশীলভাবে ব্যবহার করুন; সাইটের কার্যক্রমে বাধা দেবেন না, অননুমোদিত প্রবেশের চেষ্টা করবেন না বা স্বয়ংক্রিয় অনুরোধের অপব্যবহার করবেন না।', ur: 'آپ A Online Ruler کو قانونی ذاتی، تعلیمی اور کاروباری مقاصد کے لیے استعمال کر سکتے ہیں۔ ویب سائٹ ذمہ داری سے استعمال کریں؛ اس کے کام میں خلل نہ ڈالیں، غیر مجاز رسائی کی کوشش نہ کریں اور خودکار درخواستوں کا غلط استعمال نہ کریں۔' },
	'The ruler is a browser-based visual aid. Display dimensions, browser zoom, device settings, and calibration affect the result. Measurements are estimates unless you verify the scale against a known reference. Use a physical ruler, caliper, or other suitable instrument for safety-critical, regulated, or close-tolerance work.': { de: 'Das Lineal ist eine visuelle Hilfe im Browser. Bildschirmabmessungen, Browserzoom, Geräteeinstellungen und Kalibrierung beeinflussen das Ergebnis. Ohne Abgleich mit einer bekannten Referenz sind Messwerte Schätzungen. Verwenden Sie bei sicherheitskritischen, regulierten oder toleranzengenauen Arbeiten ein echtes Lineal, einen Messschieber oder ein geeignetes Instrument.', pt: 'A régua é um recurso visual no navegador. Dimensões da tela, zoom, configurações do dispositivo e calibração afetam o resultado. As medidas são estimativas até que a escala seja conferida com uma referência conhecida. Para trabalhos críticos de segurança, regulamentados ou com tolerâncias estreitas, use uma régua física, paquímetro ou instrumento adequado.', ar: 'المسطرة أداة مرئية تعمل في المتصفح. تؤثر أبعاد الشاشة وتكبير المتصفح وإعدادات الجهاز والمعايرة في النتيجة. تظل القياسات تقديرية ما لم تتحقق من التدريج بمرجع معروف. استخدم مسطرة فعلية أو قدمة قياس أو أداة مناسبة للأعمال الحساسة للسلامة أو الخاضعة للتنظيم أو ذات التفاوتات الدقيقة.', bn: 'রুলারটি ব্রাউজারভিত্তিক দৃশ্যমান সহায়ক। ডিসপ্লের মাপ, ব্রাউজার জুম, ডিভাইস সেটিং ও ক্যালিব্রেশন ফলকে প্রভাবিত করে। পরিচিত রেফারেন্স দিয়ে যাচাই না করলে মাপগুলো অনুমানমাত্র। নিরাপত্তা-গুরুত্বপূর্ণ, নিয়ন্ত্রিত বা সূক্ষ্ম সহনসীমার কাজে আসল রুলার, ক্যালিপার বা উপযুক্ত যন্ত্র ব্যবহার করুন।', ur: 'یہ پیمانہ براؤزر میں چلنے والا بصری معاون ہے۔ ڈسپلے کے ابعاد، براؤزر زوم، ڈیوائس کی ترتیبات اور کیلیبریشن نتیجے پر اثر انداز ہوتے ہیں۔ معلوم حوالے سے تصدیق تک پیمائش اندازاً ہے۔ حفاظتی اہمیت، ضابطہ شدہ یا باریک درستگی کے کام میں حقیقی پیمانہ، کیلپر یا مناسب آلہ استعمال کریں۔' },
	'The website design, text, code, and branding belong to A Online Ruler or its licensors. You may access and use the service as intended, but you may not copy, republish, or redistribute substantial parts of it without permission.': { de: 'Design, Texte, Code und Marke der Website gehören A Online Ruler oder dessen Lizenzgebern. Sie dürfen den Dienst bestimmungsgemäß nutzen, wesentliche Teile jedoch nicht ohne Erlaubnis kopieren, erneut veröffentlichen oder weiterverbreiten.', pt: 'O design, os textos, o código e a marca do site pertencem ao A Online Ruler ou seus licenciadores. Você pode usar o serviço conforme previsto, mas não pode copiar, republicar ou redistribuir partes substanciais sem autorização.', ar: 'تصميم الموقع ونصوصه ورموزه وعلامته التجارية مملوكة لـ A Online Ruler أو الجهات المرخّصة له. يمكنك استخدام الخدمة للغرض المقصود، لكن لا يجوز نسخ أجزاء جوهرية منها أو إعادة نشرها أو توزيعها دون إذن.', bn: 'ওয়েবসাইটের নকশা, লেখা, কোড ও ব্র্যান্ড A Online Ruler বা এর লাইসেন্সদাতাদের সম্পত্তি। নির্ধারিতভাবে পরিষেবা ব্যবহার করতে পারেন, তবে অনুমতি ছাড়া এর উল্লেখযোগ্য অংশ কপি, পুনঃপ্রকাশ বা বিতরণ করা যাবে না।', ur: 'ویب سائٹ کا ڈیزائن، متن، کوڈ اور برانڈ A Online Ruler یا اس کے لائسنس دہندگان کی ملکیت ہیں۔ آپ خدمت کو مقررہ مقصد کے مطابق استعمال کر سکتے ہیں، مگر اجازت کے بغیر اس کے اہم حصے نقل، دوبارہ شائع یا تقسیم نہیں کر سکتے۔' },
	'We work to keep the service available and accurate, but it is provided as-is and may change or be unavailable from time to time. To the extent permitted by law, A Online Ruler is not responsible for losses resulting from reliance on an unverified screen measurement or interruption of the service.': { de: 'Wir bemühen uns um Verfügbarkeit und Genauigkeit, stellen den Dienst jedoch ohne Gewähr bereit. Er kann sich ändern oder zeitweise ausfallen. Soweit gesetzlich zulässig, haftet A Online Ruler nicht für Schäden, die durch ungeprüfte Bildschirmmessungen oder eine Unterbrechung des Dienstes entstehen.', pt: 'Trabalhamos para manter o serviço disponível e preciso, mas ele é fornecido como está e pode mudar ou ficar indisponível. Na medida permitida por lei, o A Online Ruler não se responsabiliza por perdas decorrentes de medidas não verificadas na tela ou da interrupção do serviço.', ar: 'نسعى إلى إبقاء الخدمة متاحة ودقيقة، لكنها تُقدم كما هي وقد تتغير أو تتوقف مؤقتًا. بالقدر الذي يسمح به القانون، لا يتحمل A Online Ruler مسؤولية الخسائر الناتجة عن الاعتماد على قياس شاشة غير متحقق منه أو عن انقطاع الخدمة.', bn: 'পরিষেবাটি সচল ও নির্ভুল রাখতে আমরা চেষ্টা করি, তবে এটি বর্তমান অবস্থায় দেওয়া হয় এবং বদলাতে বা সাময়িকভাবে অপ্রাপ্য হতে পারে। আইনসম্মত সীমায়, যাচাই না করা স্ক্রিন মাপের ওপর নির্ভরতা বা পরিষেবা বিঘ্নে হওয়া ক্ষতির জন্য A Online Ruler দায়ী নয়।', ur: 'ہم خدمت کو دستیاب اور درست رکھنے کی کوشش کرتے ہیں، لیکن یہ جیسی ہے ویسی فراہم کی جاتی ہے اور بدل یا عارضی طور پر بند ہو سکتی ہے۔ قانون کی اجازت کی حد تک، غیر تصدیق شدہ اسکرین پیمائش پر بھروسے یا خدمت میں رکاوٹ سے ہونے والے نقصان کا A Online Ruler ذمہ دار نہیں ہوگا۔' },
	'We may revise these terms as the service evolves. Continuing to use the website after an update means you accept the revised terms.': { de: 'Wir können diese Bedingungen bei Weiterentwicklung des Dienstes überarbeiten. Wenn Sie die Website nach einer Aktualisierung weiter nutzen, stimmen Sie den geänderten Bedingungen zu.', pt: 'Podemos revisar estes termos conforme o serviço evolui. Continuar usando o site após uma atualização significa que você aceita os termos revisados.', ar: 'قد نعدّل هذه الشروط مع تطور الخدمة. استمرارك في استخدام الموقع بعد التحديث يعني موافقتك على الشروط المعدّلة.', bn: 'পরিষেবার পরিবর্তনের সঙ্গে আমরা এই শর্তাবলি সংশোধন করতে পারি। হালনাগাদের পর ওয়েবসাইট ব্যবহার চালিয়ে গেলে সংশোধিত শর্তে সম্মতি বোঝায়।', ur: 'خدمت کے ارتقا کے ساتھ ہم ان شرائط پر نظرثانی کر سکتے ہیں۔ اپ ڈیٹ کے بعد ویب سائٹ کا استعمال جاری رکھنے کا مطلب ہے کہ آپ نظرثانی شدہ شرائط قبول کرتے ہیں۔' },
};
